WITH exploded AS (SELECT id, plan, currency, tier_value FROM price_tiers LATERAL VIEW EXPLODE(discounts) e AS tier_value) SELECT CASE WHEN tier_value >= 73 THEN 'LARGE' ELSE 'SMALL' END AS tier_value_tier, SORT_ARRAY(COLLECT_SET(currency)) AS currency_list, AVG(tier_value) AS avg_tier_value, APPROX_PERCENTILE(tier_value, ARRAY(0.25, 0.5, 0.75)) AS tier_value_quartiles FROM exploded GROUP BY tier_value_tier HAVING AVG(tier_value) >= 0 ORDER BY tier_value_tier DESC;
